cat << 'EOF' > src/orchestration/tools/registry.test.ts
import {describe, it, expect} from 'vitest';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  describe('execute', () => {
    it('rejects input missing a required property with a ToolResponse and does not call executor', async () => {
      const registry = new ToolRegistry();
      let executorCalls = 0;
      registry.register(
        {
          name: 'get_weather',
          description: 'Get weather for a location',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'string'}},
            required: ['location'],
          },
        },
        async () => {
          executorCalls += 1;
          return 'sunny';
        }
      );

      const response = await registry.execute('get_weather', {});

      expect(executorCalls).toBe(0);
      expect(response).toHaveProperty('result');
      expect(response.result).toMatch(/location/);
      expect(response.result).toMatch(/required/i);
    });
  });
});
EOF
